local KTool = CS.Engine.Lib.KTool

local ActionDarkDreamLevelTargetCell = Class('ActionDarkDreamLevelTargetCell')
function ActionDarkDreamLevelTargetCell:__init()

end

function ActionDarkDreamLevelTargetCell:__delete()

end

function ActionDarkDreamLevelTargetCell:Awake()
end

function ActionDarkDreamLevelTargetCell:RefreshConditionShow(conditionVo,nodeVo,isComplete,index)
    if self.ActionDarkDreamStar then
        local cell = CfUtils.GetLuaScr(self.ActionDarkDreamStar,"Game.UI.FightReady.ChaoticRecall.Cell.ActionDarkDreamStarRootCell")
        if not isNull(cell) then
            cell:RefreshStarStatus(isComplete)
        end
    end

    KTool.SetActive(self.ImgLightBg.gameObject,isComplete)

    local listStarConditionNum = nodeVo.starConditionNum
    local listStarConditionRound = nodeVo.starConditionRound
    local questTypeVo = conditionVo
    if isNotNull(questTypeVo.condition) then
        local desc = checkString(questTypeVo.condition)
        desc = string.fmt(desc, { _target_num_ = checkString(checkInt(listStarConditionNum[index])),
                                  _target_num2_ = checkString(checkInt(checkNumber(listStarConditionNum[index] * 100))),
                                  _time_ = checkString(checkInt(listStarConditionRound[index]))})
        local str = desc
        local status = isComplete and 1 or 2
        CfUtils.SetUISwitchText(self.TxtObjectives,status)
        CfUtils.FillText(self.TxtObjectives,str)
    end
end

function ActionDarkDreamLevelTargetCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActionDarkDreamLevelTargetCell